// Mock source: the bundled synthetic data in data/sample/ (generated by scripts/generate-data.mjs and,
// for model outputs, refreshed from a live run by scripts/capture-live.mjs). Sample-mode decisions
// (early-warning actions, the challenger promotion) are kept in this browser's localStorage.
import portfolio from '@/data/sample/portfolio.json';
import queue from '@/data/sample/queue.json';
import models from '@/data/sample/models.json';
import monitoring from '@/data/sample/monitoring.json';
import type { ActionRecord, Models, Monitoring, Portfolio, Queue } from './types';

export const sample = {
  portfolio: portfolio as Portfolio,
  queue: queue as Queue,
  models: models as Models,
  monitoring: monitoring as Monitoring,
};

const ACTIONS_KEY = 'crms-sample-actions';
const PROMOTED_KEY = 'crms-sample-promoted';

export function sampleActions(): ActionRecord[] {
  if (typeof window === 'undefined') return [];
  try { return JSON.parse(window.localStorage.getItem(ACTIONS_KEY) ?? '[]'); } catch { return []; }
}
export function saveSampleAction(a: ActionRecord) {
  const all = sampleActions().filter((x) => x.accountId !== a.accountId);
  window.localStorage.setItem(ACTIONS_KEY, JSON.stringify([...all, a]));
}
export function samplePromotion(): { note: string; approver: string; at: string } | null {
  if (typeof window === 'undefined') return null;
  try { return JSON.parse(window.localStorage.getItem(PROMOTED_KEY) ?? 'null'); } catch { return null; }
}
export function saveSamplePromotion(p: { note: string; approver: string; at: string } | null) {
  if (p) window.localStorage.setItem(PROMOTED_KEY, JSON.stringify(p));
  else window.localStorage.removeItem(PROMOTED_KEY);
}
export function resetSample() {
  window.localStorage.removeItem(ACTIONS_KEY);
  window.localStorage.removeItem(PROMOTED_KEY);
}
